const staticData = $getWorkflowStaticData('global');
const norm = $json;
const key = 'flap_' + norm.host + '_' + norm.service_name;
const WINDOW_MS = 30 * 60 * 1000;
const MAX_RESTARTS = 3;
const DAILY_MAX = 5;
const now = Date.now();

const today = new Date().toISOString().slice(0, 10);
const dayKey = 'daily_' + today + '_' + norm.host + '_' + norm.service_name;

const history = (staticData[key] || []).filter(ts => (now - ts) < WINDOW_MS);
const restartCountToday = staticData[dayKey] || 0;

const isWindowFlap = history.length >= MAX_RESTARTS;
const isDailyLimit = restartCountToday >= DAILY_MAX;
const isFlap = isWindowFlap || isDailyLimit;
const flap_reason = isDailyLimit ? 'limite_diario' : 'janela_30min';

if (!isFlap) {
  history.push(now);
  staticData[key] = history;
  staticData[dayKey] = restartCountToday + 1;
}

return [{ json: { ...norm, flap: isFlap, flap_attempts: history.length, flap_reason, restart_count_today: isFlap ? restartCountToday : restartCountToday + 1 } }];

const norm = $json;
const now = new Date().toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo' });
const isDailyLimit = norm.flap_reason === 'limite_diario';
const title = isDailyLimit ? 'Limite Diario Atingido — Remediacao Suspensa' : 'Servico em Loop — Remediacao Automatica Suspensa';
const acao = isDailyLimit
  ? norm.restart_count_today + ' reinicializacoes hoje — limite de 5/dia atingido. Intervencao manual necessaria.'
  : 'Caiu ' + norm.flap_attempts + 'x em 30 min — intervencao manual necessaria';

return [{ json: { teams_body: JSON.stringify({
  '@type': 'MessageCard',
  '@context': 'http://schema.org/extensions',
  themeColor: 'FF8C00',
  summary: 'Anti-Flap: ' + norm.service_name + ' em ' + norm.host,
  sections: [{
    activityTitle: title,
    activitySubtitle: norm.host,
    facts: [
      { name: 'Servico',                value: norm.service_name },
      { name: 'Reinicializacoes hoje',  value: String(norm.restart_count_today) },
      { name: 'Tentativas (30m)',       value: String(norm.flap_attempts) },
      { name: 'Severidade',            value: norm.severity },
      { name: 'Trigger',               value: norm.trigger_name },
      { name: 'Hora',                  value: now },
      { name: 'Acao',                  value: acao }
    ],
    markdown: true
  }]
}) } }];

// ============================================================
// CONFIGURAÇÃO DE RESTRIÇÕES — edite aqui
// ============================================================

// Servidores onde TOTVS (RM.*) e IIS nunca reiniciam automaticamente
const SERVIDORES_SEM_REINICIO_TOTVS_IIS = [
  'FINDES-MIG-PORTAL',
  'FINDES-MIG-APRM',
  'FINDES-MIG-JOBS',
  'FINDES-MIG-RMUPDATE',
  'FINDES-HML-PORTAL',
  'HML-PORTALRM02',
  'FINDES-HML-APRM',
  'FINDES-HML-RMJOBS',
  'FINDES-HML-RMUPDATE',
];

// Padrões de serviço TOTVS/IIS bloqueados nos servidores acima
const PADROES_TOTVS_IIS = [
  /^rm\./i,    // Qualquer RM.* (TOTVS)
  /^w3svc$/i,  // IIS - World Wide Web Publishing Service
  /^was$/i,    // IIS - Windows Process Activation Service
];

// Servidores de produção: reinício permitido SOMENTE das 08:00 às 19:59
// Fora dessa janela o reinício automático é bloqueado
const RESTRICOES_HORARIO = {
  'PRD-APRM':     { inicio: 8, fim: 19 },
  'PRD-APRM02':   { inicio: 8, fim: 19 },
  'PRD-BDRM':     { inicio: 8, fim: 19 },
  'PRD-FLUIG':    { inicio: 8, fim: 19 },
  'PRD-PORTAL':   { inicio: 8, fim: 19 },
  'PRD-RMJOBS01': { inicio: 8, fim: 19 },
  'PRD-RMJOBS02': { inicio: 8, fim: 19 },
  'PRD-RMJOBS03': { inicio: 8, fim: 19 },
  'PRD-RMUPDATE': { inicio: 8, fim: 19 },
  'PRD-TAF':      { inicio: 8, fim: 19 },
  'PRD-TLS':      { inicio: 8, fim: 19 },
  'PRD-TSS':      { inicio: 8, fim: 19 },
};

// ============================================================

const norm = $json;
const service = norm.service_name || '';
const host = norm.host || '';
const hostUp = host.toUpperCase();

const now = new Date(new Date().toLocaleString('en-US', { timeZone: 'America/Sao_Paulo' }));
const hora = now.getHours();

// 1. Bloqueio permanente: TOTVS/IIS em servidores MIG e HML
const isServidorRestrito = SERVIDORES_SEM_REINICIO_TOTVS_IIS.some(s => s.toUpperCase() === hostUp);
if (isServidorRestrito) {
  const isTotvsOuIIS = PADROES_TOTVS_IIS.some(p => p.test(service));
  if (isTotvsOuIIS) {
    return [{ json: { ...norm, bloqueado: true, motivo_bloqueio: 'Servico TOTVS/IIS bloqueado neste servidor (MIG/HML): ' + host + ' / ' + service } }];
  }
}

// 2. Restrição de horário: servidores de produção
const restricaoKey = Object.keys(RESTRICOES_HORARIO).find(k => k.toUpperCase() === hostUp);
if (restricaoKey) {
  const r = RESTRICOES_HORARIO[restricaoKey];
  const foraJanela = hora < r.inicio || hora > r.fim;
  if (foraJanela) {
    return [{ json: { ...norm, bloqueado: true, motivo_bloqueio: 'Fora da janela de reinicio automatico (08h-20h). Hora atual: ' + hora + 'h. Servidor: ' + host } }];
  }
}

return [{ json: { ...norm, bloqueado: false, motivo_bloqueio: '' } }];

const norm = $('Normalizar Campos').item.json;
const motivo = $json.motivo_bloqueio || 'Restricao configurada no workflow';
const now = new Date().toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo' });

return [{ json: { teams_body: JSON.stringify({
  '@type': 'MessageCard',
  '@context': 'http://schema.org/extensions',
  themeColor: 'FF8C00',
  summary: 'Remediacao bloqueada: ' + norm.service_name + ' em ' + norm.host,
  sections: [{
    activityTitle: 'Remediacao Bloqueada por Restricao',
    activitySubtitle: norm.host,
    facts: [
      { name: 'Servico',    value: norm.service_name },
      { name: 'Motivo',     value: motivo },
      { name: 'Severidade', value: norm.severity },
      { name: 'Trigger',    value: norm.trigger_name },
      { name: 'Hora',       value: now }
    ],
    markdown: true
  }]
}) } }];

const buscarResult = $('Zabbix API — Buscar Host').item.json;
const hostname = $('Normalizar Campos').item.json.host;

if (!buscarResult.result || buscarResult.result.length === 0) {
  throw new Error('Host nao encontrado no Zabbix: ' + hostname);
}

const hostid            = parseInt(buscarResult.result[0].hostid);
const scriptid          = parseInt($env.ZABBIX_SCRIPT_ID);
const eventlog_scriptid = parseInt($env.ZABBIX_EVENTLOG_SCRIPT_ID);
const service_name      = $('Normalizar Campos').item.json.service_name;
const event_id          = $('Normalizar Campos').item.json.event_id;
const severity          = $('Normalizar Campos').item.json.severity;
const trigger_name      = $('Normalizar Campos').item.json.trigger_name;
const now               = new Date().toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo' });

return [{
  json: {
    execute_body: JSON.stringify({
      jsonrpc: '2.0',
      method: 'script.execute',
      params: { scriptid, hostid, manualinput: service_name },
      id: 2
    }),
    eventlog_body: JSON.stringify({
      jsonrpc: '2.0',
      method: 'script.execute',
      params: { scriptid: eventlog_scriptid, hostid, manualinput: service_name },
      id: 3
    }),
    success_body: JSON.stringify({
      jsonrpc: '2.0',
      method: 'event.acknowledge',
      params: {
        eventids: [event_id],
        action: 4,
        message: '[n8n] Servico ' + service_name + ' reiniciado automaticamente via Zabbix Agent em ' + hostname + ' em ' + now
      },
      id: 1
    }),
    failure_body: JSON.stringify({
      jsonrpc: '2.0',
      method: 'event.acknowledge',
      params: {
        eventids: [event_id],
        action: 4,
        message: '[n8n] FALHA ao reiniciar servico ' + service_name + ' em ' + hostname + ' via Zabbix Agent. Intervencao manual necessaria.'
      },
      id: 1
    })
  }
}];

const serviceStatus = $('Zabbix API — Executar Script').item.json.result?.value || 'N/D';
const logInfo = ($('Buscar Log Windows').item.json.result?.value || '').trim() || 'Nao disponivel';
const norm = $('Normalizar Campos').item.json;
const restartCountToday = $('Verificar Anti-Flap').item.json.restart_count_today || 1;
const now  = new Date().toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo' });

return [{
  json: {
    teams_body: JSON.stringify({
      '@type': 'MessageCard',
      '@context': 'http://schema.org/extensions',
      themeColor: restartCountToday >= 2 ? 'FFA500' : '00B050',
      summary: 'Servico reiniciado: ' + norm.service_name + ' em ' + norm.host,
      sections: [{
        activityTitle: 'Servico Reiniciado Automaticamente',
        activitySubtitle: norm.host,
        facts: [
          { name: 'Servico',               value: norm.service_name },
          { name: 'Status apos reinicio',  value: serviceStatus },
          { name: 'Severidade',            value: norm.severity },
          { name: 'Trigger',               value: norm.trigger_name },
          { name: 'Hora',                  value: now },
          { name: 'Reinicializacoes hoje', value: String(restartCountToday) + (restartCountToday >= 2 ? ' (atencao: reinicializacoes repetidas)' : '') },
          { name: 'Ultimo evento no log',  value: logInfo }
        ],
        markdown: true
      }]
    })
  }
}];

const norm = $('Normalizar Campos').item.json;
const logInfo = ($('Buscar Log Windows').item.json.result?.value || '').trim() || 'Nao disponivel';
const now = new Date().toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo' });

return [{
  json: {
    teams_body: JSON.stringify({
      '@type': 'MessageCard',
      '@context': 'http://schema.org/extensions',
      themeColor: 'FF0000',
      summary: 'Falha de remediacao: ' + norm.service_name + ' em ' + norm.host,
      sections: [{
        activityTitle: 'Falha ao Reiniciar Servico',
        activitySubtitle: norm.host,
        facts: [
          { name: 'Servico',              value: norm.service_name },
          { name: 'Severidade',           value: norm.severity },
          { name: 'Trigger',              value: norm.trigger_name },
          { name: 'Hora',                 value: now },
          { name: 'Ultimo evento no log', value: logInfo }
        ],
        markdown: true
      }]
    })
  }
}];
